# -----------------------------------------------------------------------------
# Make Visual Workspace glass blur visibly affect the live material.
# -----------------------------------------------------------------------------
p = 'Halo/Views/SurfaceView.swift'
s = read(p)
start = s.find('private struct OpenNotchBackgroundView: View {')
end = s.find('\nprivate struct OpenNotchSurfaceChrome: View {', start)
if start < 0 or end < 0:
    raise SystemExit('anchor not found: OpenNotchBackgroundView')
new_runtime = '''private struct OpenNotchBackgroundView: View {\n    let options: OpenNotchAppearance\n    let fallback: Appearance\n    let theme: Theme\n    @ObservedObject var system: SystemService\n\n    private var effectiveAppearance: Appearance { options.baseAppearance(fallback) }\n    private var glassBlur: Double { min(30, max(0, options.blur ?? fallback.blur)) }\n\n    var body: some View {\n        baseBackground\n            .contrast(options.contrast ?? 1)\n            .overlay((options.tintColor ?? WidgetColor(red: 0.35, green: 0.55, blue: 1)).color.opacity(options.tintOpacity ?? 0))\n            .overlay(Color.orange.opacity(max(0, options.warmth ?? 0) * 0.06))\n            .overlay(Color.blue.opacity(max(0, -(options.warmth ?? 0)) * 0.05))\n            .overlay {\n                if (options.grain ?? 0) > 0 {\n                    Canvas { context, size in\n                        let amount = min(0.35, max(0, options.grain ?? 0))\n                        let step: CGFloat = 7\n                        var x: CGFloat = 1\n                        var seed: UInt64 = UInt64(size.width * 31 + size.height * 17)\n                        while x < size.width {\n                            var y: CGFloat = 1\n                            while y < size.height {\n                                seed = seed &* 2862933555777941757 &+ 3037000493\n                                let n = Double((seed >> 33) & 255) / 255.0\n                                if n > 0.64 { context.fill(Path(CGRect(x: x, y: y, width: 1, height: 1)), with: .color(.white.opacity(amount * 0.18))) }\n                                y += step\n                            }\n                            x += step\n                        }\n                    }.allowsHitTesting(false)\n                }\n            }\n    }\n\n    @ViewBuilder private var baseBackground: some View {\n        if effectiveAppearance.background == .glass {\n            ZStack {\n                SurfaceBackground(appearance: effectiveAppearance, theme: theme, expanded: true, system: system)\n                glassStrengthLayer\n            }\n        } else {\n            SurfaceBackground(appearance: effectiveAppearance, theme: theme, expanded: true, system: system)\n        }\n    }\n\n    @ViewBuilder private var glassStrengthLayer: some View {\n        let strength = min(1, max(0, glassBlur / 30))\n        if glassBlur < 0.5 {\n            Color.clear\n        } else if glassBlur < 7 {\n            Rectangle().fill(.ultraThinMaterial).opacity(0.18 + strength * 0.42)\n        } else if glassBlur < 14 {\n            Rectangle().fill(.thinMaterial).opacity(0.22 + strength * 0.46)\n        } else if glassBlur < 21 {\n            Rectangle().fill(.regularMaterial).opacity(0.28 + strength * 0.50)\n        } else if glassBlur < 27 {\n            Rectangle().fill(.thickMaterial).opacity(0.32 + strength * 0.54)\n        } else {\n            Rectangle().fill(.ultraThickMaterial).opacity(0.38 + strength * 0.58)\n        }\n    }\n}\n'''
s = s[:start] + new_runtime + s[end:]
write(p, s)

print('Synced Background tab with Visual Workspace, pruned irrelevant controls, and fixed Visual Workspace glass strength.')
